    mC68[7] = (s16)cM_rndFX(32768.0f);
    mC68[8] = (s16)cM_rndFX(32768.0f);
    mC68[9] = (s16)cM_rndFX(32768.0f);
    mC68[10] = (s16)cM_rndFX(32768.0f);
    mC68[11] = (s16)cM_rndFX(32768.0f);
